def update_issue(identifier,text,verified=False):
    global s
    pattern=re.compile(r"(^### "+re.escape(identifier)+r"\n)(.*?)(?=^### |\Z)",re.M|re.S)
    match=pattern.search(s);assert match,identifier
    body=match[2]
    body=re.sub(r"Обновлено: \*\*[^*]+\*\*", "Обновлено: **2026-10-20**",body,count=1)
    if verified:
        body=body.replace("Статус: **открыта**","Статус: **проверена**",1)
    body=body.rstrip()+"\n- "+log+": "+text+"\n\n"
    s=s[:match.start()]+match[1]+body+s[match.end():]

